804: size_t ID3_GetGenreNum(const ID3_Tag *tag)
805: {
806:   char *sGenre = ID3_GetGenre(tag);
807:   size_t ulGenre = 0xFF;
808:   if (NULL == sGenre)
809:   {
810:     return ulGenre;
811:   }
812: 
813:   // If the genre string begins with "(ddd)", where "ddd" is a number, then
814:   // "ddd" is the genre number---get it
815:   if (sGenre[0] == '(')
816:   {
817:     char *pCur = &sGenre[1];
818:     while (isdigit(*pCur))
819:     {
820:       pCur++;
821:     }
822:     if (*pCur == ')')
823:     {
824:       // if the genre number is greater than 255, its invalid.
825:       ulGenre = dami::min(0xFF, atoi(&sGenre[1]));
826:     }
827:   }
828: 
829:   delete [] sGenre;
830:   return ulGenre;
831: }
