833: size_t ID3_GetV1GenreNum(char* sGenre)
834: {
835:   dami::String tmpgenre;
836:   size_t ulGenre = 0xFF;
837:   uint32 iStart = 0;
838:   uint32 digits;
839: 
840:   if (strlen(sGenre) < 3)
841:     return ulGenre;
842: 
843:   // If the genre string begins with "(ddd)", where "ddd" is a number, then
844:   // "ddd" is the genre number---get it
845:   while (1)
846:   {
847:     digits = 0;
848:     if (sGenre[iStart] == '(')
849:     {
850:       char *pCur = &sGenre[iStart + 1];
851:       if (strlen(pCur) >= 3 && strncmp(pCur, "RX)", 3) == 0)
852:       {
853:         iStart += 4;
854:         tmpgenre.append("(RX)", 4);
855:         continue;
856:       }
857:       else if (strlen(pCur) >= 3 && strncmp(pCur, "CR)", 3) == 0)
858:       {
859:         iStart += 4;
860:         tmpgenre.append("(CR)", 4);
861:         continue;
862:       }
863:       if (*pCur == '\0')
864:         break; //allready at end of text, only text has "(\0"
865:       if (*pCur == '(')
866:       { // starts with "((" so rest is text
867:         sGenre += iStart;
868:         if (strlen(sGenre) > 0)
869:           tmpgenre.append(sGenre, strlen(sGenre));
870:         sGenre -= iStart;
871:         break;
872:       }
873:       if (*pCur == ')')//empty "()"
874:       {
875:         iStart += 2;
876:         continue; //ignore them, doesn't get copied in tmpgenre
877:       }
878:       if (isdigit(*pCur))
879:       {
880:         while (isdigit(*pCur))
881:         {
882:           pCur++;
883:           ++digits;
884:         }
885:         if (*pCur == ')')
886:         {
887:           ulGenre = atoi(&sGenre[iStart + 1]); //should be made to only check nr of digits long
888:           // it's invalid when bigger than the actual number of v1 genre's
889:           if (ulGenre >= ID3_NR_OF_V1_GENRES)
890:           {
891:             ulGenre = 0xFF;
892:             iStart += 2 + digits; //two for "(" and ")"
893:             continue; //try to find a better one
894:           }
895:           else
896:           { //copy the remainder of the text, we found a valid genre number
897:             sGenre += iStart + 2 + digits; //two for "(" and ")"
898:             if (strlen(sGenre) > 0)
899:               tmpgenre.append(sGenre, strlen(sGenre));
900:             sGenre -= iStart + 2 + digits;
901:             break;
902:           }
903:         }
904:         else //some gibberish like "(123BLAH
905:           ++iStart;
906:       }
907:       else //some gibberish like "(BLAH")
908:         ++iStart;
909:     }
910:     else if (sGenre[iStart] == '\0')
911:       break;
912:     else
913:     {
914:       tmpgenre.append(sGenre[iStart], 1);
915:       ++iStart;
916:     }
917:   }
918:   if (tmpgenre.size() > 0)
919:   {
920:      sprintf(sGenre, tmpgenre.c_str());
921:   }
922: 
923:   return ulGenre;
924: }
