935:     { //found, copy 0 to iStart and iStart to remainder
936:       if (iStart > 0)
937:       {
938:         text -= iStart; //get the original string back
939:         tmptext.append(text, iStart);
940:       }
941:       if (strlen(text) > (iStart + strlen(chars)))
942:       { //copy the remainder
943:         text += strlen(chars) + iStart;
944:         tmptext.append(text, strlen(text));
945:         text -= strlen(chars) + iStart;
946:       }
947:       if (tmptext.size() > 0)
948:       {
949:         sprintf(text, tmptext.c_str());
950:       }
951:       else
952:         text[0] = '\0';
953:       return true;
954:     }
955:     else
956:     {
957:       ++text;
958:       ++iStart;
959:     }
960:   } ;
961:   //not found
962:   return false;
