982: ID3_Frame* ID3_AddGenre(ID3_Tag* tag, size_t genreNum, char* genre, bool add_v1_genre_number, bool add_v1_genre_description, bool addRXorCR, bool replace)
983: {
984: /* This routine should work for the following (all examples):
985:  * genrenumbers can come within char* genre using (number), by genreNum, or if char* genre matches a v1 genrenumber
986:  * "(20)InvalidDescription" --> "(20)Alternative"
987:  * "(RX)(CR)(20)" --> "(RX)(CR)(20)Alternative"
988:  * "(24)(40)(20)" --> "(24)(40)(20)Soundtrack, AlternRock, Alternative"
989:  * "(RX)(CR)Alternative" --> "(RX)(CR)(20)Alternative"
990:  */
991:   size_t newGenreNum1 = 0xFF; //this is the one found in the text as (number)
992:   size_t newGenreNum2 = 0xFF; //this is the one found in the text by matching the string
993:   bool writeRX = false;
994:   bool writeCR = false;
995:   char* tmpgenre1 = LEAKTESTNEW(char[1024]);// = NULL;
996:   const char* tmpgenre = NULL;
997:   const char* remainder = NULL;
998:   dami::String* newgenre = LEAKTESTNEW(dami::String);
999:   int iCompare;
1000: 
1001:   if (add_v1_genre_number == false && add_v1_genre_description == false)
1002:   { // you don't want me to do anything? Fine by me
1003:     delete newgenre;
1004:     delete [] tmpgenre1;
1005:     return NULL;
1006:   }
1007:   if (genre != NULL && strlen(genre) == 0)
1008:     genre = NULL;
1009: 
1010:   if (genre != NULL)
1011:   { //see if there are references to v1 genre numbers in it, e.g. "(" + number + ")" + description
1012:     if (strlen(genre) > 1023)
1013:     {
1014:       delete newgenre;
1015:       delete [] tmpgenre1;
1016:       return NULL;
1017:     }
1018:     sprintf(tmpgenre1, "%s", genre);
1019: 
1020:     newGenreNum1 = ID3_GetV1GenreNum(tmpgenre1); //get's the first and strips it
1021:     if (strlen(tmpgenre1) != 0)
1022:     { //see if there are references to v1 genre numbers in it, e.g. "(" + number + ")" + description
1023:       writeRX = ID3_HasChars(tmpgenre1, "(RX)");
1024:     }
1025:     if (strlen(tmpgenre1) != 0)
1026:     { //see if there are references to v1 genre numbers in it, e.g. "(" + number + ")" + description
1027:       writeCR = ID3_HasChars(tmpgenre1, "(CR)");
1028:     }
1029:     // search for an additional genre number, from a match
1030:     if (strlen(tmpgenre1) != 0) //try to find an additional number from the remaining genre
1031:     {
1032:       for (newGenreNum2 = 0; newGenreNum2 < ID3_NR_OF_V1_GENRES; ++newGenreNum2)
1033:       {
1034:         tmpgenre = ID3_V1GENRE2DESCRIPTION(newGenreNum2);
1035:         // if tmpgenre = "Blues" and tmpgenre1 = "Blues, HardRock" they should match i accept a space, a comma and a ; as de;imters
1036:         // if tmpgenre = "Pop" and tmpgenre1 = "Pop-Folk" they shouldn't match
1037:         // if tmpgenre = "Jazz" and tmpgenre1 = "Jazz+Funk" they shouldn't match
1038:         iCompare = ID3_strncasecmp(tmpgenre, tmpgenre1, 23); //biggest genre is "Contemporary Christian" which is 22 chars
1039:         if (iCompare == 0) //perfect match, nothing remains
1040:         { //strip it off
1041:           tmpgenre1[0] = '\0';
1042:           break;
1043:         }
1044:         else if (iCompare == -2 && (tmpgenre1[strlen(tmpgenre)] == ',' || tmpgenre1[strlen(tmpgenre)] == ' ' || tmpgenre1[strlen(tmpgenre)] == ';' )) //tmpgenre was earlier null terminated
1045:         {
1046:           iCompare = strlen(tmpgenre);
1047:           tmpgenre1 += iCompare;
1048:           remainder = tmpgenre1; //remainder now holds the remainder of the string
1049:           tmpgenre1 -= iCompare; //reset for delete
1050:           break;
1051:         }
1052:       } //for
1053:       if ( newGenreNum2 == ID3_NR_OF_V1_GENRES) //no match
1054:         remainder = tmpgenre1;
1055:     }
1056:   }
1057:   // after breaking, now trying to rebuild things
1058:   if (add_v1_genre_number)
1059:   { //they want a genrenumber
1060:     char* sGenre = LEAKTESTNEW(char[6]);
1061:     size_t size;
1062:     if (genreNum < ID3_NR_OF_V1_GENRES)
1063:     {
1064:       size = sprintf(sGenre, "(%lu)", (luint) genreNum);
1065:       newgenre->append(sGenre, size);
1066:     }
1067:     if (newGenreNum1 < ID3_NR_OF_V1_GENRES && newGenreNum1 != genreNum)
1068:     {
1069:       size = sprintf(sGenre, "(%lu)", (luint) newGenreNum1);
1070:       newgenre->append(sGenre, size);
1071:     }
1072:     if (newGenreNum2 < ID3_NR_OF_V1_GENRES && newGenreNum2 != genreNum && newGenreNum2 != newGenreNum1)
1073:     {
1074:       size = sprintf(sGenre, "(%lu)", (luint) newGenreNum2);
1075:       newgenre->append(sGenre, size);
1076:     }
1077:     delete [] sGenre;
1078:   }
1079:   if (addRXorCR)
1080:   { // they want CR or RX o be added, if there is
1081:     if (writeRX)
1082:       newgenre->append("(RX)", 4);
1083:     if (writeCR)
1084:       newgenre->append("(CR)", 4);
1085:   }
1086:   if (add_v1_genre_description)
1087:   {
1088:     if (genreNum < ID3_NR_OF_V1_GENRES)
1089:     {
1090:       tmpgenre = ID3_V1GENRE2DESCRIPTION(genreNum);
1091:       newgenre->append(tmpgenre, strlen(tmpgenre));
1092:     }
1093:     if (newGenreNum1 < ID3_NR_OF_V1_GENRES && newGenreNum1 != genreNum)
1094:     {
1095:       if (genreNum < ID3_NR_OF_V1_GENRES) //also valid
1096:         newgenre->append(", ", 2);
1097:       tmpgenre = ID3_V1GENRE2DESCRIPTION(newGenreNum1);
1098:       newgenre->append(tmpgenre, strlen(tmpgenre));
1099:     }
1100:     if (newGenreNum2 < ID3_NR_OF_V1_GENRES && newGenreNum2 != genreNum && newGenreNum2 != newGenreNum1)
1101:     {
1102:       if (genreNum < ID3_NR_OF_V1_GENRES || newGenreNum1 < ID3_NR_OF_V1_GENRES)
1103:         newgenre->append(", ", 2);
1104:       tmpgenre = ID3_V1GENRE2DESCRIPTION(newGenreNum2);
1105:       newgenre->append(tmpgenre, strlen(tmpgenre));
1106:     }
1107:     // add any remaining text
1108:     if (remainder != NULL)
1109:       newgenre->append(remainder, strlen(remainder));
1110:   }
1111:   //clean memory
1112:   if (newgenre->size() == 0)
1113:   {
1114:     delete newgenre;
1115:     delete [] tmpgenre1;
1116:     return NULL;
1117:   }
1118: 
1119:   sprintf(tmpgenre1, newgenre->c_str());
1120:   delete newgenre;
1121:   ID3_Frame* newframe = ID3_AddGenre(tag, tmpgenre1, replace);
1122:   delete [] tmpgenre1;
1123:   return newframe;
1124: }
