1339:                              const char *lang, ID3_ContentType type,
1340:                              bool replace)
1341: {
1342:   ID3_Frame* frame = NULL;
1343:   // language and descriptor should be mandatory
1344:   if ((NULL == lang) || (NULL == desc))
1345:   {
1346:     return NULL;
1347:   }
1348: 
1349:   // check if a SYLT frame of this language or descriptor already exists
1350:   ID3_Frame* frmExist = tag->Find(ID3FID_SYNCEDLYRICS, ID3FN_LANGUAGE, lang);
1351:   if (!frmExist)
1352:   {
1353:     frmExist = tag->Find(ID3FID_SYNCEDLYRICS, ID3FN_DESCRIPTION, desc);
1354:   }
1355: 
1356:   if (NULL != tag && NULL != data)
1357:   {
1358:     if (replace && frmExist)
1359:     {
1360:       frmExist = tag->RemoveFrame (frmExist);
1361:       delete frmExist;
1362:       frmExist = NULL;
1363:     }
1364: 
1365:     // if the frame still exist, cannot continue
1366:     if (frmExist)
1367:     {
1368:       return NULL;
1369:     }
1370: 
1371:     ID3_Frame* frame = LEAKTESTNEW( ID3_Frame(ID3FID_SYNCEDLYRICS));
1372: 
1373:     frame->GetField(ID3FN_LANGUAGE)->Set(lang);
1374:     frame->GetField(ID3FN_DESCRIPTION)->Set(desc);
1375:     frame->GetField(ID3FN_TIMESTAMPFORMAT)->Set(format);
1376:     frame->GetField(ID3FN_CONTENTTYPE)->Set(type);
1377:     frame->GetField(ID3FN_DATA)->Set(data, datasize);
1378:     tag->AttachFrame(frame);
1379:   }
1380: 
1381:   return frame;
1382: }
