338: flags_t ID3_TagImpl::Update(flags_t ulTagFlag)
339: {
340:   flags_t tags = ID3TT_NONE;
341: 
342:   fstream file;
343:   String filename = this->GetFileName();
344:   _last_error = openWritableFile(filename, file);
345:   _file_size = getFileSize(file);
346: 
347:   if (_last_error == ID3E_NoFile)
348:   {
349:     _last_error = createFile(filename, file);
350:   }
351:   if (_last_error == ID3E_ReadOnly)
352:   {
353:     return tags;
354:   }
355: 
356:   if ((ulTagFlag & ID3TT_ID3V2) && this->HasChanged())
357:   {
358:     ID3_V2Spec spec2use;
359:     if (this->UserUpdatedSpec) // if the spec is too old, upgrade anyway. And never use experimental ones
360:       spec2use = this->GetSpec() < ID3V2_3_0 ? ID3V2_LATEST : this->GetSpec();
361:     else
362:       spec2use = ID3V2_LATEST; //write ID3V2_LATEST as default
363: 
364:     this->SetSpec(spec2use);
365:     this->checkFrames();
366:     _prepended_bytes = RenderV2ToFile(*this, file);
367:     if (_prepended_bytes < 17) //17 = minimal tag size, errors should not be higher numbered than 16
368:     {
369:       //must be an error
370:       _last_error = (ID3_Err)_prepended_bytes;
371:       _prepended_bytes = 0;
372:     }
373:     if (_prepended_bytes)
374:     {
375:       tags |= ID3TT_ID3V2;
376:     }
377:   }
378: 
379:   if ((ulTagFlag & ID3TT_ID3V1) &&
380:       (!this->HasTagType(ID3TT_ID3V1) || this->HasChanged()))
381:   {
382:     size_t tag_bytes = RenderV1ToFile(*this, file);
383:     if (tag_bytes)
384:     {
385:       // only add the tag_bytes if there wasn't an id3v1 tag before
386:       if (! _file_tags.test(ID3TT_ID3V1))
387:       {
388:         _appended_bytes += tag_bytes;
389:       }
390:       tags |= ID3TT_ID3V1;
391:     }
392:   }
393:   _changed = false;
394:   _file_tags.add(tags);
395:   _file_size = getFileSize(file);
396:   file.close();
397:   return tags;
398: }
