400: flags_t ID3_TagImpl::Strip(flags_t ulTagFlag)
401: {
402:   flags_t ulTags = ID3TT_NONE;
403:   const size_t data_size = ID3_GetDataSize(*this);
404: 
405:   // First remove the v2 tag, if requested
406:   if (ulTagFlag & ID3TT_PREPENDED & _file_tags.get())
407:   {
408:     fstream file;
409:     _last_error = openWritableFile(this->GetFileName(), file);
410:     if (ID3E_NoError != _last_error)
411:     {
412:       return ulTags;
413:     }
414:     _file_size = getFileSize(file);
415: 
416:     // We will remove the id3v2 tag in place: since it comes at the beginning
417:     // of the file, we'll effectively move all the data that comes after the
418:     // tag back n bytes, where n is the size of the id3v2 tag.  Once we've
419:     // copied the data, we'll truncate the file.
420:     file.seekg(this->GetPrependedBytes(), ios::beg);
421: 
422:     uchar aucBuffer[BUFSIZ];
423: 
424:     // The nBytesRemaining variable indicates how many bytes are to be copied
425:     size_t nBytesToCopy = data_size;
426: 
427:     // Here we increase the nBytesToCopy by the size of any tags that appear
428:     // at the end of the file if we don't want to strip them
429:     if (!(ulTagFlag & ID3TT_APPENDED))
430:     {
431:       nBytesToCopy += this->GetAppendedBytes();
432:     }
433: 
434:     // The nBytesRemaining variable indicates how many bytes are left to be
435:     // moved in the actual file.
436:     // The nBytesCopied variable keeps track of how many actual bytes were
437:     // copied (or moved) so far.
438:     size_t
439:       nBytesRemaining = nBytesToCopy,
440:       nBytesCopied = 0;
441:     while (!file.eof())
442:     {
443: #if (defined(__GNUC__) && __GNUC__ == 2)
444:       size_t nBytesToRead = (size_t)dami::min((unsigned int)(nBytesRemaining - nBytesCopied), (unsigned int)BUFSIZ);
445: #else
446:       size_t nBytesToRead = min((unsigned int)(nBytesRemaining - nBytesCopied), (unsigned int)BUFSIZ);
447: #endif
448:       file.read((char *)aucBuffer, nBytesToRead);
449:       size_t nBytesRead = file.gcount();
450: 
451:       if (nBytesRead != nBytesToRead)
452:       {
453:         // TODO: log this
454:         //cerr << "--- attempted to write " << nBytesRead << " bytes, "
455:         //     << "only wrote " << nBytesWritten << endl;
456:       }
457:       if (nBytesRead > 0)
458:       {
459:         long offset = nBytesRead + this->GetPrependedBytes();
460:         file.seekp(-offset, ios::cur);
461:         file.write((char *)aucBuffer, nBytesRead);
462:         file.seekg(this->GetPrependedBytes(), ios::cur);
463:         nBytesCopied += nBytesRead;
464:       }
465: 
466:       if (nBytesCopied == nBytesToCopy || nBytesToRead < BUFSIZ)
467:       {
468:         break;
469:       }
470:     }
471:     file.close();
472:   }
473: 
474:   size_t nNewFileSize = data_size;
475: 
476:   if ((_file_tags.get() & ID3TT_APPENDED) && (ulTagFlag & ID3TT_APPENDED))
477:   {
478:     ulTags |= _file_tags.get() & ID3TT_APPENDED;
479:   }
480:   else
481:   {
482:     // if we're not stripping the appended tags, be sure to increase the file
483:     // size by those bytes
484:     nNewFileSize += this->GetAppendedBytes();
485:   }
486: 
487:   if ((ulTagFlag & ID3TT_PREPENDED) && (_file_tags.get() & ID3TT_PREPENDED))
488:   {
489:     // If we're stripping the ID3v2 tag, there's no need to adjust the new
490:     // file size, since it doesn't account for the ID3v2 tag size
491:     ulTags |= _file_tags.get() & ID3TT_PREPENDED;
492:   }
493:   else
494:   {
495:     // add the original prepended tag size since we don't want to delete it,
496:     // and the new file size represents the file size _not_ counting the ID3v2
497:     // tag
498:     nNewFileSize += this->GetPrependedBytes();
499:   }
500: 
501:   if (ulTags && (truncate(_file_name.c_str(), nNewFileSize) == -1))
502:   {
503:     // log this
504:     _last_error = ID3E_NoFile;
505:     return 0;
506:   }
507: 
508:   _prepended_bytes = (ulTags & ID3TT_PREPENDED) ? 0 : _prepended_bytes;
509:   _appended_bytes  = (ulTags & ID3TT_APPENDED)  ? 0 : _appended_bytes;
510:   _file_size = data_size + _prepended_bytes + _appended_bytes;
511: 
512:   _changed = _file_tags.remove(ulTags) || _changed;
513: 
514:   return ulTags;
515: }
